LOCK TABLES `job_fair_events` WRITE;
/*!40000 ALTER TABLE `job_fair_events` DISABLE KEYS */;
INSERT INTO `job_fair_events` VALUES (1,1,'رحلة الجاهزية المهنية\" لمعرض التوظيف 2026','keynote','تدشين البرنامج العلمي المصاحب لمعرض التوظيف 2026، والذي ينطلق تحت مفهوم موحد: «رحلة الجاهزية المهنية: من الجامعة ← التأهيل ← سوق العمل ← بناء مسار مهني مستدام». يستعرض اللقاء محاور البرنامج وأهدافه في تقليص الفجوة المهارية وتعزيز التنافسية محلياً ودولياً.','• رسالة البرنامج: نحو خريج أكثر جاهزية وقدرة على المنافسة في سوق العمل.\r\n• استعراض هيكل البرنامج العلمي: Masterclass رئيسية، 4 ورش عمل تطبيقية، وجلستان حواريتان.\r\n• دور مكتب تدريب الخريجين كشريك مستمر للخريج في مختلف مراحل تطوره المهني.\r\n• آفاق الشراكة والتكامل مع الشركات والمؤسسات الموظفة.','المنيب محمد الشريف','موظف بوحدة الدعم التقني','افتتاح وتدشين فعاليات البرنامج العلمي المصاحب لمعرض التوظيف 2026،','events/speakers/3dBzEKZFVhMcRj8wO2Z2sX0t1miio6bDV33hvH9Y.jpg','2026-11-10 09:30:00','2026-11-10 10:15:00','مسرح العلوم','كافة الخريجين والطلبة  وممثلو الشركات',400,'open',1,'2026-10-11 08:36:58','2026-10-12 12:13:33'),(2,1,'Masterclass: اصنع قيمتك المهنية - كيف تصبح الشخص الذي تبحث عنه الشركات؟','masterclass','الفعالية الرئيسية الكبرى ضمن البرنامج المصاحب تحت عنوان: «من موظف عادي إلى قيمة لا يمكن الاستغناء عنها». تجربة ملهمة وعملية حول كيفية بناء قيمة مهنية حقيقية لا تبدأ عند توقيع عقد الوظيفة، بل قبل ذلك عبر فهم نقاط القوة وتطوير المهارات وتقديم قيمة مضافة داخل بيئة العمل.','• كيف تبني قيمة حقيقية في سوق العمل وتصبح مرشحاً استثنائياً؟\n• الفرق بين مجرد البحث عن وظيفة وبناء مسار مهني طويل المدى.\n• ما الذي يجعل شخصاً ما مميزاً بنظر أصحاب العمل ومدراء الشركات؟\n• المهارات الحيوية التي تصنع الفرق في بداية المسار المهني.\n• أهمية التواصل والتأثير والعلاقات المهنية الاستراتيجية.\n• كيف تتعامل بذكاء مع الرفض والتحديات المهنية؟\n• استراتيجية التطوير الذاتي المستمر في سوق عمل متغير ومتسارع.\n• كيف تصنع فرصك بنفسك بدلاً من الانتظار السلبي.','أ. صالح أبو المجد','مدرب مؤسسي ومدرب قيادة، وخبير في المبيعات وتطوير الأعمال (مصر)','يمتلك خبرة واسعة في التدريب المؤسسي وتطوير القيادات والفرق، ويركز محتواه المهني على موضوعات القيادة والتواصل والتأثير والمبيعات وتطوير الأداء، كما يتمتع بحضور مهني وتأثير جماهيري واسع عبر منصة LinkedIn ومنصات التواصل العربية. (المرشح البديل: د. عطية).',NULL,'2026-11-10 10:30:00','2026-11-10 12:30:00','المسرح الجامعي الرئيسي - مجمع الكليات','الخريجون، الباحثون عن عمل، والطلبة المتوقع تخرجهم بجميع التخصصات',350,'open',1,'2026-10-11 08:36:58','2026-10-11 08:36:58'),(3,1,'ورشة عمل (1): خريطة سوق العمل - أين تتجه الوظائف؟ وما المهارات التي ستصنع الفرق؟','workshop','ورشة تفاعلية تهدف لمساعدة المشاركين على الانتقال من التفكير التقليدي في «ما الوظيفة التي أريدها؟» إلى سؤال أكثر واقعية وذكاءً: «ما المهارات التي يحتاجها السوق، وكيف يمكنني الاستعداد لها؟».','• الاتجاهات الجديدة والقطاعات الصاعدة في سوق العمل الإقليمي والدولي.\n• الوظائف والمجالات الناشئة وأثر الذكاء الاصطناعي والتكنولوجيا.\n• المهارات التقنية والسلوكية (Soft & Hard Skills) الأكثر طلباً.\n• العالقة بين التخصص الجامعي ومسارات العمل الحديثة غير النمطية.\n• كيف يكتشف الخريج اتجاهه المهني بناءً على إمكانياته وشغفه؟\n• صياغة خطة شخصية واضحة لتطوير المهارات خلال 6 إلى 12 شهراً.','أ. محمد قويش','صانع محتوى ومدرب متخصص في التكنولوجيا والمهارات والتطوير المهني (مصر)','يقدم محتوى شبابي وتفاعلي يربط بين التطور التقني والمهارات المطلوبة والتحولات التي يشهدها سوق العمل ووظائف المستقبل، مع أسلوب تطبيقي مبسط يلائم الطلبة وحديثي التخرج. (المرشح البديل: م. عبد الله بطاح).',NULL,'2026-11-10 13:00:00','2026-11-10 14:30:00','قاعة المحاضرات والورش (أ) - مبنى المؤتمرات','الطلبة والخريجون الراغبون في فهم اتجاهات التوظيف الحديثة والمجالات الناشئة',80,'open',0,'2026-10-11 08:36:58','2026-10-11 08:36:58'),(4,1,'جلسة حوارية (1): من ليبيا إلى العالم - قصص ليبية صنعت مسارات دولية','panel_discussion','جلسة حوارية ملهمة تقدم نماذج واقعية لشخصيات ليبية رائدة نجحت في اختراق الأسواق الدولية والعمل مع كبرى المؤسسات والجامعات العالمية، لإثبات إمكانية الوصول إلى العالمية انطلاقاً من ليبيا.','• كيف بدأت الرحلة المهنية وما هي أول فرصة شكلت نقطة التحول الحقيقية؟\n• المهارات والسمات الشخصية التي مكنت من التميز والمنافسة في محافل دولية.\n• أبرز التحديات والعقبات وكيفية تجاوزها وتحويلها لدروس نجاح.\n• كيف تختلف بيئات وثقافات العمل الدولية عن بيئة العمل المحلية؟\n• ماذا يحتاج الخريج الليبي اليوم ليكون مستعداً للفرص العابرة للحدود والعمل عن بعد؟\n• خطوات عملية واستراتيجيات لبناء مسار عالمي انطلاقاً من أرض الوطن.','عبد الرحيم قدمور، محمد علي الضراط، د. محمد أبوروي','نخبة من القيادات والخبراء الليبيين ذوي التجارب والمناصب الدولية','تضم الجلسة: عبد الرحيم قدمور (مهني في قطاع التكنولوجيا بخبرة في شركات عالمية مثل IBM)، محمد علي الضراط (قائد تنفيذي بخبرة دولية ويرتبط بالمصرف الليبي الخارجي)، د. محمد أبوروي (طبيب ورائد أعمال تقني، مؤسس Atarona Ventures و Speetar، خريج Harvard و MIT Sloan).',NULL,'2026-11-10 15:00:00','2026-11-10 16:30:00','المسرح الجامعي الرئيسي - مجمع الكليات','كافة خريجي وطلبة الجامعة المهتمين بريادة الأعمال والمسارات المهنية الدولية',280,'open',1,'2026-10-11 08:36:58','2026-10-11 08:36:58'),(5,1,'ورشة عمل (2): من الشهادة إلى سوق العمل - كيف تبني جاهزيتك المهنية قبل أول وظيفة؟','workshop','تعد هذه الورشة من أكثر الفعاليات ارتباطاً بمهمة مكتب تدريب الخريجين، حيث تركز على تحويل الخريج من حامل شهادة أكاديمية إلى مرشح جاهز يمتلك الكفاءة والأدوات العملية المطلوبة للالتحاق الفوري بالوظيفة.','• لماذا لا تكفي الشهادة الجامعية وحدها للظفر بالفرص النوعية؟\n• الفارق الجوهري بين المؤهل الأكاديمي والكفاءة المهنية على أرض الواقع.\n• تحليل فجوة المهارات وتشخيص نقاط القوة والضعف.\n• المهارات الجوهرية التي يبحث عنها أصحاب العمل (حل المشكلات، المرونة، العمل الجماعي).\n• دور التدريب العملي والمشاريع التطبيقية والتطوع في بناء سيرة قوية.\n• صياغة خطة تطوير مهني شخصية قابلة للتنفيذ والقياس.\n• كيف تكتسب خبرة عملية مقنعة وموثوقة قبل وظيفتك الأولى؟','د. طاهر نصر','مدرب ومتحدث دولي في مجالات التطوير وبناء القدرات (مصر)','متحدث ومستشار تدريب متخصص في تنمية المهارات القيادية والشخصية وبناء القدرات المهنية للخريجين لتهيئتهم لدخول سوق العمل بكفاءة وثقة عالية. (البدلاء: د. منذر الحرم - ليبيا/المملكة المتحدة، أ. هبة السمان).',NULL,'2026-11-11 09:30:00','2026-11-11 11:30:00','قاعة المحاضرات والورش (أ) - مبنى المؤتمرات','الخريجون حديثاً والطلبة في سنتهم الدراسية الأخيرة',85,'open',0,'2026-10-11 08:36:58','2026-10-11 08:36:58'),(6,1,'ورشة عمل (3): كيف تفكر الشركات؟ من السيرة الذاتية إلى قرار التوظيف','workshop','تهدف هذه الورشة لنقل وجهة نظر مسؤولي التوظيف والمدراء إلى الخريج مباشرة، وتعريفه بما يدور خلف الكواليس منذ استلام السيرة الذاتية وفلترتها حتى المقابلة النهائية واتخاذ قرار التعيين.','• كيف تُفرز السير الذاتية في الشركات الحديثة وأنظمة ATS الرقمية؟\n• الأخطاء الشائعة والقاتلة التي تتسبب في استبعاد السيرة الذاتية فوراً.\n• ما الذي يبحث عنه مسؤول التوظيف بدقة بين سطور سيرتك الذاتية؟\n• بناء الهوية المهنية الاحترافية وأهمية التواجد المؤثر على LinkedIn.\n• تفكيك وتحليل الوصف الوظيفي (Job Description) لمطابقة متطلباته.\n• استراتيجيات الاستعداد النفسي والمهني للمقابلات الوظيفية وأسئلة السلوك.\n• معادلة المهارة في مقابل سنوات الخبرة: كيف تبرز ميزتك التنافسية؟\n• أسرار التفاوض الوظيفي والتواصل المهني الذكي بعد المقابلة.','أ. يمنى جمال','Career Coach ومدربة متخصصة في استقطاب المواهب وإدارة الموارد البشرية (مصر)','تمتلك أكثر من 12 عاماً من الخبرة في إدارة المواهب والتوظيف بالشركات الإقليمية، واستشارات التوجيه المهني وتطبيقات الذكاء الاصطناعي في الموارد البشرية. (البدلاء: أ. هبة السمان، أ. رغد الدخاخني).',NULL,'2026-11-11 11:45:00','2026-11-11 13:15:00','قاعة التدريب التفاعلي (ب) - مبنى المؤتمرات','كافة الباحثين عن عمل والخريجين الراغبين في اجتياز مقابلات التوظيف بنجاح',90,'open',1,'2026-10-11 08:36:58','2026-10-11 08:36:58'),(7,1,'ورشة عمل (4): AI Career Toolkit - كيف تستخدم الذكاء الاصطناعي لتطوير مسارك المهني؟','workshop','ورشة عمل تطبيقية بالكامل يستخدم خلالها المشاركون أدوات فعلية للذكاء الاصطناعي، ليخرج كل مشارك بنتائج ملموسة تشمل سيرة ذاتية مطورة، وتحسين ملف LinkedIn، وتحديد فجوة المهارات، وإعداد خطة تعلم شخصية.','• الهندسة العكسية وتحليل إعلانات الوظائف بواسطة الذكاء الاصطناعي.\n• تحسين وصياغة السيرة الذاتية الاحترافية الموجهة لكل دور وظيفي.\n• تطوير وبناء محتوى الحساب المهني على LinkedIn بأسلوب جاذب.\n• اكتشاف الفجوات المهارية ورسم مسار تعلم ذاتي مخصص ومجاني.\n• استخدام الذكاء الاصطناعي لمحاكاة المقابلات الوظيفية وتلقي تقييم لحظي.\n• الممارسات الأخلاقية والمهنية لاستخدام أدوات الذكاء الاصطناعي في بيئة العمل.','م. عبد الله بطاح','متخصص ومدرب في الذكاء الاصطناعي والتحول الرقمي (الأردن)','خبير ومدرب رائد في توظيف أدوات الذكاء الاصطناعي التوليدي والتقنيات الحديثة لتطوير الأداء الوظيفي وتسريع المهام المهنية وتطوير الكوادر الشابة. (المرشح البديل: أ. محمد قويش).',NULL,'2026-11-11 13:30:00','2026-11-11 15:00:00','مختبر الابتكار الرقمي والحاسوب - كلية تقنية المعلومات','الخريجون والطلبة المهتمون باستغلال الذكاء الاصطناعي في البحث والتطوير والعمل',65,'open',1,'2026-10-11 08:36:58','2026-10-11 08:36:58'),(8,1,'جلسة حوارية (2): من الجامعة إلى سوق العمل - كيف نغلق الفجوة بين مخرجات التعليم واحتياجات أصحاب العمل؟','panel_discussion','جلسة استراتيجية هي الأقرب لرسالة مكتب تدريب الخريجين، تهدف للخروج بتوصيات تنفيذية ملزمة ومبادرات مشتركة لتقليص الفجوة وتفعيل التدريب العملي الميداني وتطوير جاهزية الخريجين للمنافسة.','• ما الذي يحتاجه أصحاب العمل والشركات فعلياً من الخريج الجامعي اليوم؟\n• أين توجد الفجوة الحالية بين مناهج الجامعة ومتطلبات العمل الميداني؟\n• دور التدريب التعاوني والمشاريع التطبيقية المشتركة في سد الفجوة.\n• كيف يمكن للقطاعين العام والخاص المساهمة الفعالة في إعداد الخريجين؟\n• ما المهارات المستقبلية التي يجب إدراجها في منظومة التأهيل الجامعي؟\n• آليات تفعيل دور مكتب تدريب الخريجين في بناء شراكات استراتيجية مستدامة.\n• إطلاق حزمة توصيات تنفيذية مشتركة تتبناها الجامعة والشركات الشريكة.','جامعة طرابلس + مكتب تدريب الخريجين + مدراء الموارد البشرية بالشركات الكبرى','طاولة مستديرة رفيعة المستوى: الجامعة، أصحاب العمل، وخبراء التدريب','تجمع الجلسة قيادات جامعة طرابلس، وإدارة مكتب تدريب الخريجين، ومسؤولي الموارد البشرية من قطاعات الاتصالات، النفط والغاز، المصارف، والتقنية، لبلورة مبادرات وحلول تشاركية مستدامة.',NULL,'2026-11-11 15:15:00','2026-11-11 16:45:00','المسرح الجامعي الرئيسي - مجمع الكليات','الأكاديميون، مدراء الموارد البشرية، أصحاب العمل، ممثلو الشركات، والخريجون',300,'open',1,'2026-10-11 08:36:58','2026-10-11 08:36:58'),(9,1,'عيادة الإرشاد المهني الفردي ومراجعة السير الذاتية (Career Clinic)','workshop','مساحة استشارية مفتوحة طوال فعاليات اليوم الثاني توفر للخريجين فحصاً دقيقاً لملفاتهم وسيرهم الذاتية، ومراجعة حساباتهم على منصة LinkedIn من قبل خبراء موارد بشرية معتمدين.','• تدقيق محتوى السيرة الذاتية وتنسيقها البصري والمعياري.\n• استشارات فردية سريعة حول الاستعداد لمقابلات الشركات المشاركة بالمعرض.\n• توجيه المسار المهني واختيار القطاعات الأنسب لكل تخصص.\n• نصائح لتعزيز الظهور المهني والتشبيك مع مسؤولي الشركات الحاضرة.','نخبة من مستشاري التوجيه المهني ومسؤولي التوظيف','فريق الإرشاد المهني بمكتب تدريب الخريجين وخبراء HR','جلسات إرشاد وتوجيه فردية (1-on-1) تستهدف فحص وتدقيق السير الذاتية للمشاركين وتقديم نصائح مخصصة لتطوير ملفاتهم المهنية والإجابة عن تساؤلاتهم حول المقابلات الوظيفية.',NULL,'2026-11-11 10:00:00','2026-11-11 14:00:00','صالة التوجيه المهني - بهو المعرض الرئيسي','الخريجون والطلبة المسجلون بالمعرض الراغبون بمراجعة فورية لملفاتهم',120,'open',0,'2026-10-11 08:36:58','2026-10-11 08:36:58');
/*!40000 ALTER TABLE `job_fair_events` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `job_fair_projects`
--

DROP TABLE IF EXISTS `job_fair_projects`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `job_fair_projects` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `job_fair_id` bigint(20) unsigned NOT NULL,
  `user_id` bigint(20) unsigned DEFAULT NULL,
  `title` varchar(255) NOT NULL,
  `faculty` varchar(255) NOT NULL,
  `department` varchar(255) NOT NULL,
  `graduation_year` int(11) NOT NULL DEFAULT 2026,
  `project_type` varchar(255) DEFAULT NULL,
  `main_category` varchar(255) DEFAULT NULL,
  `academic_year` varchar(255) DEFAULT '2025/2026',
  `supervisor_name` varchar(255) DEFAULT NULL,
  `supervisor_title` varchar(255) DEFAULT NULL,
  `team_members` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`team_members`)),
  `summary` text DEFAULT NULL,
  `problem_statement` text DEFAULT NULL,
  `solution_statement` text DEFAULT NULL,
  `objectives` text DEFAULT NULL,
  `description` longtext DEFAULT NULL,
  `technical_specifications` text DEFAULT NULL,
  `key_outcomes` text DEFAULT NULL,
  `market_viability` text DEFAULT NULL,
  `poster_image` varchar(255) DEFAULT NULL,
  `cover_image` varchar(255) DEFAULT NULL,
  `gallery_images` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`gallery_images`)),
  `video_url` varchar(255) DEFAULT NULL,
  `project_url` varchar(255) DEFAULT NULL,
  `contact_email` varchar(255) DEFAULT NULL,
  `student_university_id` varchar(255) DEFAULT NULL,
