INSERT INTO `job_fair_projects` VALUES (1,1,NULL,'منصة \"نبض\" للرعاية الصحية الذكية والتشخيص المبكر باستخدام الذكاء الاصطناعي','كلية تقنية المعلومات','هندسة البرمجيات والذكاء الاصطناعي',2026,NULL,NULL,'2025/2026','د. طارق ميلاد القمودي','أستاذ مشارك - قسم هندسة البرمجيات','[{\"name\":\"\\u0639\\u0645\\u0631 \\u0639\\u0628\\u062f \\u0627\\u0644\\u0628\\u0627\\u0633\\u0637 \\u0627\\u0644\\u0637\\u0627\\u0647\\u0631\",\"role\":\"\\u0645\\u0647\\u0646\\u062f\\u0633 \\u0630\\u0643\\u0627\\u0621 \\u0627\\u0635\\u0637\\u0646\\u0627\\u0639\\u064a \\u0648\\u0646\\u0645\\u0627\\u0630\\u062c \\u062a\\u0639\\u0644\\u0645 \\u0639\\u0645\\u064a\\u0642\",\"email\":\"omar.tahir@tripoliuniversity.edu.ly\",\"phone\":\"+218 91 234 5678\",\"linkedin\":\"https:\\/\\/linkedin.com\\/in\\/omar-tahir\"},{\"name\":\"\\u0633\\u0627\\u0631\\u0629 \\u0639\\u0628\\u062f \\u0627\\u0644\\u0644\\u0647 \\u0627\\u0644\\u0632\\u0646\\u062a\\u0627\\u0646\\u064a\",\"role\":\"\\u0645\\u0637\\u0648\\u0631 \\u0648\\u0627\\u062c\\u0647\\u0627\\u062a \\u0648\\u062a\\u062c\\u0631\\u0628\\u0629 \\u0645\\u0633\\u062a\\u062e\\u062f\\u0645 (Full-Stack)\",\"email\":\"sara.zintani@tripoliuniversity.edu.ly\",\"phone\":\"+218 92 345 6789\",\"linkedin\":\"https:\\/\\/linkedin.com\\/in\\/sara-zintani\"},{\"name\":\"\\u0645\\u062d\\u0645\\u062f \\u0625\\u0628\\u0631\\u0627\\u0647\\u064a\\u0645 \\u0627\\u0644\\u0648\\u0631\\u0641\\u0644\\u064a\",\"role\":\"\\u0645\\u0647\\u0646\\u062f\\u0633 \\u0628\\u0646\\u064a\\u0629 \\u0633\\u062d\\u0627\\u0628\\u064a\\u0629 \\u0648\\u0642\\u0648\\u0627\\u0639\\u062f \\u0628\\u064a\\u0627\\u0646\\u0627\\u062a\",\"email\":\"mohamed.warfalli@tripoliuniversity.edu.ly\",\"phone\":\"+218 94 567 8901\",\"linkedin\":\"https:\\/\\/linkedin.com\\/in\\/mohamed-warfalli\"}]','منصة رقمية متكاملة تقدم نظام فرز وتشخيص مبكر للأشعة السينية والتقارير الطبية بالاعتماد على خوارزميات الرؤية الحاسوبية (Computer Vision)، مع تطبيق للهاتف يربط المريض بالمركز الصحي مباشرة.',NULL,NULL,'• تقليص زمن انتظار التشخيص الأولي في أقسام الطوارئ والمستشفيات بنسبة 60%.\n• رفع دقة رصد الأنماط غير الطبيعية في صور الأشعة السينية إلى أكثر من 94%.\n• توفير سجل صحي إلكتروني آمن ومحمي طبقاً لمعايير الخصوصية الطبية العالمية.','يعالج هذا المشروع مشكلة نقص الكوادر التخصصية في المراكز الطبية النائية من خلال نموذج خفيف الوزن يمكن نشره محلياً بدون الحاجة لاتصال دائم بالإنترنت. تم تدريب النموذج على أكثر من 45 ألف صورة شعاعية مصنفة مع التحقق الإكلينيكي بالتعاون مع أطباء مستشفى طرابلس المركزي. يحتوي النظام على لوحة تحكم متطورة للطبيب تدعم المراجعة اليدوية وإبداء التوصيات وإصدار الوصفات الدوائية الرقمية.',NULL,NULL,NULL,NULL,NULL,NULL,'https://youtube.com/watch?v=demo-nabd','https://github.com/nabd-health/ai-platform',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'IT-01','published',1,452,'2026-10-12 14:15:03','2026-10-12 14:15:03'),(2,1,NULL,'نظام شبكات الطاقة الشمسية الذكية مع التوزيع الديناميكي ومراقبة إنترنت الأشياء (IoT)','كلية الهندسة','الهندسة الكهربائية والإلكترونية',2026,NULL,NULL,'2025/2026','د. مفتاح محمد الزوي','أستاذ التحكم والأنظمة الذكية','[{\"name\":\"\\u0639\\u0628\\u062f \\u0627\\u0644\\u0631\\u062d\\u0645\\u0646 \\u0641\\u0631\\u062c \\u0627\\u0644\\u0643\\u064a\\u0644\\u0627\\u0646\\u064a\",\"role\":\"\\u062a\\u0635\\u0645\\u064a\\u0645 \\u0627\\u0644\\u062f\\u0648\\u0627\\u0626\\u0631 \\u0648\\u0645\\u062a\\u062d\\u0643\\u0645\\u0627\\u062a \\u0627\\u0644\\u0640 Microcontroller\",\"email\":\"abdurahman.k@tripoliuniversity.edu.ly\",\"phone\":\"+218 91 333 4455\",\"linkedin\":\"https:\\/\\/linkedin.com\"},{\"name\":\"\\u0623\\u0633\\u0627\\u0645\\u0629 \\u062e\\u0627\\u0644\\u062f \\u0628\\u0646 \\u0633\\u0627\\u0633\\u064a\",\"role\":\"\\u0628\\u0631\\u0645\\u062c\\u0629 \\u0623\\u0646\\u0638\\u0645\\u0629 \\u0625\\u0646\\u062a\\u0631\\u0646\\u062a \\u0627\\u0644\\u0623\\u0634\\u064a\\u0627\\u0621 \\u0648\\u0634\\u0628\\u0643\\u0627\\u062a \\u0627\\u0644\\u062d\\u0633\\u0627\\u0633\\u0627\\u062a\",\"email\":\"osama.b@tripoliuniversity.edu.ly\",\"phone\":\"+218 92 444 5566\",\"linkedin\":\"https:\\/\\/linkedin.com\"},{\"name\":\"\\u0641\\u0627\\u0637\\u0645\\u0629 \\u0627\\u0644\\u0635\\u0627\\u062f\\u0642 \\u0627\\u0644\\u0641\\u0631\\u062c\\u0627\\u0646\\u064a\",\"role\":\"\\u062a\\u062d\\u0644\\u064a\\u0644 \\u0627\\u0644\\u0623\\u062d\\u0645\\u0627\\u0644 \\u0648\\u0643\\u0641\\u0627\\u0621\\u0629 \\u0627\\u0644\\u0637\\u0627\\u0642\\u0629 \\u0627\\u0644\\u0645\\u062a\\u062c\\u062f\\u062f\\u0629\",\"email\":\"fatima.f@tripoliuniversity.edu.ly\",\"phone\":\"+218 93 555 6677\",\"linkedin\":\"https:\\/\\/linkedin.com\"}]','نظام إلكتروني لإدارة وتوزيع الطاقة المولدة من الألواح الكهروضوئية بذكاء بين البطاريات والشبكة العامة والأحمال الحيوية، مع مراقبة لحظية عبر أجهزة استشعار إنترنت الأشياء وسحابة بيانات.',NULL,NULL,'• تحسين كفاءة استغلال الطاقة الشمسية في المنشآت والمؤسسات بنسبة تصل إلى 28%.\n• التحويل التلقائي الآمن بين مصادر الطاقة لتفادي انقطاع التيار الكهربائي.\n• كشف الأعطال وتراجع أداء الألواح مبكراً عبر تحليل بيانات التيار والجهد والحرارة.','يتكون النموذج الأولي من وحدة تحكم هجينة (Hybrid Inverter Controller) تعتمد على معالج ESP32 ولوغاريتمات التتبع لأقصى نقطة قدرة (MPPT). يتيح النظام للمستخدم عبر شاشة اللمس وتطبيق الموبايل مراقبة الإنتاج والاستهلاك والتنبؤ بكميات الطاقة المولدة للأيام القادمة بالاعتماد على توقعات الطقس المحلية.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'https://github.com/iot-solar-grid',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'ENG-04','published',1,389,'2026-10-12 14:15:04','2026-10-12 14:15:04'),(3,1,NULL,'تصميم وتصنيع روبوت فحص الأنابيب النفطية المستقل تحت سطح البحر (AUV)','كلية الهندسة','الهندسة الميكانيكية والصناعية',2026,NULL,NULL,'2025/2026','د. عادل البشير الترهوني','رئيس قسم الهندسة الميكانيكية','[{\"name\":\"\\u0645\\u0627\\u0644\\u0643 \\u0639\\u0627\\u062f\\u0644 \\u0627\\u0644\\u0628\\u0643\\u0648\\u0634\",\"role\":\"\\u0627\\u0644\\u062a\\u0635\\u0645\\u064a\\u0645 \\u0627\\u0644\\u0647\\u064a\\u062f\\u0631\\u0648\\u062f\\u064a\\u0646\\u0627\\u0645\\u064a\\u0643\\u064a \\u0648\\u0646\\u0645\\u0630\\u062c\\u0629 \\u0627\\u0644\\u0640 CAD\\/CFD\",\"email\":\"malik.b@tripoliuniversity.edu.ly\",\"phone\":\"+218 91 777 8899\",\"linkedin\":\"https:\\/\\/linkedin.com\"},{\"name\":\"\\u0625\\u064a\\u0647\\u0627\\u0628 \\u0641\\u0648\\u0632\\u064a \\u0627\\u0644\\u0645\\u0632\\u0648\\u063a\\u064a\",\"role\":\"\\u0623\\u0646\\u0638\\u0645\\u0629 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0648\\u0627\\u0644\\u0645\\u062d\\u0631\\u0643\\u0627\\u062a \\u062a\\u062d\\u062a \\u0627\\u0644\\u0645\\u0627\\u0626\\u064a\\u0629 \\u0648\\u0639\\u0632\\u0644 \\u0627\\u0644\\u0636\\u063a\\u0637\",\"email\":\"ehab.m@tripoliuniversity.edu.ly\",\"phone\":\"+218 92 888 9900\",\"linkedin\":\"https:\\/\\/linkedin.com\"},{\"name\":\"\\u0628\\u0644\\u0627\\u0644 \\u0631\\u0645\\u0636\\u0627\\u0646 \\u0627\\u0644\\u0634\\u0631\\u064a\\u0641\",\"role\":\"\\u0623\\u0646\\u0638\\u0645\\u0629 \\u0627\\u0644\\u0627\\u0633\\u062a\\u0634\\u0639\\u0627\\u0631 \\u0628\\u0627\\u0644\\u0645\\u0648\\u062c\\u0627\\u062a \\u0627\\u0644\\u0635\\u0648\\u062a\\u064a\\u0629 \\u0648\\u0645\\u0639\\u0627\\u0644\\u062c\\u0629 \\u0627\\u0644\\u0635\\u0648\\u0631\",\"email\":\"belal.s@tripoliuniversity.edu.ly\",\"phone\":\"+218 94 999 0011\",\"linkedin\":\"https:\\/\\/linkedin.com\"}]','غواصة روبوتية ذاتية القيادة مجهزة بكاميرات فحص بالموجات فوق الصوتية ومستشعرات تسرب للكشف عن تآكل خطوط الأنابيب والمنصات النفطية البحرية وتخفيض تكاليف الصيانة والمخاطر البشرية.',NULL,NULL,'• تقليل تكلفة فحص الأنابيب البحرية ومخاطر إرسال غطاسي الأعماق بنسبة تفوق 75%.\n• الرصد الدقيق للشروخ وتآكل الجدران بمقاييس المليمتر قبل حدوث كوارث التسرب.\n• القدرة على العمل المستمر تحت ضغط حتى عمق 120 متراً لمدة تصل إلى 6 ساعات.','صُنّع هيكل الغواصة من ألياف الكربون ومواد مقاومة للصدأ مع نظام طفو إلكتروستاتيكي متزن. يحتوي الروبوت على نظام ملاحة بالقصور الذاتي (INS) متكامل مع سونار بحري، وتُعالج لقطات الفيديو بالذكاء الاصطناعي على حاسب مدمج (NVIDIA Jetson) لاكتشاف الشروخ وتسجيل إحداثياتها بدقة GPS مصحوبة بتقرير سلامة فوري.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'ENG-12','published',1,515,'2026-10-12 14:15:04','2026-10-12 14:15:04'),(4,1,NULL,'استخلاص وتطوير جزيئات نانوية علاجية من نباتات البيئة الليبية لعلاج الالتهابات المقاومة','كلية الصيدلة','الصيدلة الصناعية والرقابة الدوائية',2026,NULL,NULL,'2025/2026','د. نجلاء سالم التاجوري','أستاذ العقاقير والنباتات الطبية','[{\"name\":\"\\u0622\\u064a\\u0629 \\u0645\\u0635\\u0637\\u0641\\u0649 \\u0627\\u0644\\u0646\\u0639\\u0627\\u0633\",\"role\":\"\\u0627\\u0644\\u0627\\u0633\\u062a\\u062e\\u0644\\u0627\\u0635 \\u0648\\u0627\\u0644\\u062a\\u062d\\u0644\\u064a\\u0644 \\u0627\\u0644\\u0643\\u064a\\u0645\\u064a\\u0627\\u0626\\u064a \\u0627\\u0644\\u0637\\u064a\\u0641\\u064a (HPLC)\",\"email\":\"aya.naas@tripoliuniversity.edu.ly\",\"phone\":\"+218 91 112 2334\",\"linkedin\":\"https:\\/\\/linkedin.com\"},{\"name\":\"\\u0631\\u064a\\u0627\\u0646 \\u0639\\u0628\\u062f \\u0627\\u0644\\u062d\\u0643\\u064a\\u0645 \\u0627\\u0644\\u0645\\u0628\\u0631\\u0648\\u0643\",\"role\":\"\\u062a\\u062d\\u0636\\u064a\\u0631 \\u0627\\u0644\\u0646\\u0648\\u0627\\u0642\\u0644 \\u0627\\u0644\\u0646\\u0627\\u0646\\u0648\\u064a\\u0629 \\u0648\\u0627\\u0644\\u062a\\u0648\\u0635\\u064a\\u0644 \\u0627\\u0644\\u062f\\u0648\\u0627\\u0626\\u064a \\u0627\\u0644\\u0645\\u0633\\u062a\\u0647\\u062f\\u0641\",\"email\":\"rayan.m@tripoliuniversity.edu.ly\",\"phone\":\"+218 92 223 3445\",\"linkedin\":\"https:\\/\\/linkedin.com\"},{\"name\":\"\\u0625\\u064a\\u0646\\u0627\\u0633 \\u0633\\u0627\\u0644\\u0645 \\u0634\\u0646\\u064a\\u0628\",\"role\":\"\\u0627\\u0644\\u0627\\u062e\\u062a\\u0628\\u0627\\u0631\\u0627\\u062a \\u0627\\u0644\\u0628\\u064a\\u0648\\u0644\\u0648\\u062c\\u064a\\u0629 \\u0648\\u062f\\u0631\\u0627\\u0633\\u0629 \\u0627\\u0644\\u0633\\u0645\\u064a\\u0629 \\u0627\\u0644\\u0645\\u062e\\u0628\\u0631\\u064a\\u0629\",\"email\":\"inas.s@tripoliuniversity.edu.ly\",\"phone\":\"+218 93 334 4556\",\"linkedin\":\"https:\\/\\/linkedin.com\"}]','بحث تطبيقي صيدلاني يستغل المركبات النشطة في نباتات الزعتر والعرعر الليبي عبر تحميلها على جزيئات نانوية لزيادة ثباتها وفاعليتها في القضاء على البكتيريا المقاومة للمضادات الحيوية التقليدية.',NULL,NULL,'• ابتكار بدائل علاجية طبيعية للميكروبات المقاومة للمضادات الحيوية (MRSA).\n• زيادة التوافر الحيوي للمستخلصات النباتية عبر تقنية التغليف النانوي (Nanocapsules).\n• إثبات الجدوى الاقتصادية لتصنيع مستحضرات صيدلانية محلية الصنع بجودة منافسة عالمياً.','أظهرت النتائج المخبرية للمشروع تثبيطاً فعالاً لنمو السلالات البكتيرية المعزولة بتركيزات أقل بنسبة 5 أضعاف مقارنة بالمستخلص الخام دون أي سمية على الخلايا الحية. تم تحضير النموذج في صورة هلام جلدي (Hydrogel) قابل للتطبيق الموضعي السريع لعلاج الحروق والجروح الملتهبة.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'PHARM-02','published',0,295,'2026-10-12 14:15:04','2026-10-12 14:15:04'),(5,1,NULL,'نظام أمني لرصد الاختراقات السحابية في الوقت الحقيقي باستخدام التعلم العميق والـ Graph Neural Networks','كلية العلوم','علوم الحاسوب والأمن السيبراني',2026,NULL,NULL,'2025/2026','د. خالد علي الفيتوري','أستاذ الأمن السيبراني والشبكات','[{\"name\":\"\\u062d\\u0633\\u0627\\u0645 \\u0623\\u062d\\u0645\\u062f \\u0627\\u0644\\u0635\\u0627\\u062f\\u0642\",\"role\":\"\\u0628\\u0646\\u0627\\u0621 \\u0646\\u0645\\u0627\\u0630\\u062c \\u0627\\u0644\\u0640 GNN \\u0648\\u062a\\u062d\\u0644\\u064a\\u0644 \\u0633\\u0644\\u0648\\u0643 \\u0627\\u0644\\u0634\\u0628\\u0643\\u0627\\u062a\",\"email\":\"hossam.s@tripoliuniversity.edu.ly\",\"phone\":\"+218 91 555 6688\",\"linkedin\":\"https:\\/\\/linkedin.com\"},{\"name\":\"\\u0645\\u0631\\u064a\\u0645 \\u0639\\u0628\\u062f \\u0627\\u0644\\u0639\\u0638\\u064a\\u0645 \\u0628\\u0646 \\u063a\\u0631\\u0633\\u0629\",\"role\":\"\\u0647\\u0646\\u062f\\u0633\\u0629 \\u062e\\u0637\\u0648\\u0637 \\u0627\\u0644\\u0628\\u064a\\u0627\\u0646\\u0627\\u062a \\u0627\\u0644\\u0633\\u062d\\u0627\\u0628\\u064a\\u0629 (Data Pipelines)\",\"email\":\"maryam.b@tripoliuniversity.edu.ly\",\"phone\":\"+218 92 666 7799\",\"linkedin\":\"https:\\/\\/linkedin.com\"}]','منظومة دفاع سيبراني متقدمة تحول حركة البيانات السحابية إلى تمثيل بياني شبكي (Graph) لاكتشاف الهجمات المعقدة والمتسللين الصامتين (Zero-Day Exploits) في أجزاء من الثانية.',NULL,NULL,'• خفض الإنذارات الكاذبة (False Positives) بنسبة 45% مقارنة بأنظمة الـ IDS التقليدية.\n• كشف سلاسل الهجمات المعقدة الممتدة عبر عدة خوادم سحابية افتراضية.\n• الاستجابة الفورية بعزل الحاويات المخترقة تلقائياً دون إيقاف الخدمة العامة.','يعتمد النظام على خوارزميات التعلم البياني العميق (GNN) لربط الأحداث الأمنية المتفرقة ورسم خريطة التهديد اللحظية. خضع النظام لاختبارات اختراق افتراضية مكثفة حقق خلالها نسبة دقة 98.2% في التمييز بين الحركة الطبيعية للمستخدمين والهجمات الموجهة (APT).',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'https://github.com/cloud-gnn-ids',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'SCI-08','published',0,330,'2026-10-12 14:15:04','2026-10-12 14:15:04'),(6,1,NULL,'نموذج تقييم الجدارة الائتمانية للمشاريع الناشئة في ليبيا باستخدام تقنيات الـ FinTech والذكاء المالي','كلية الاقتصاد والعلوم السياسية','المصارف والتمويل وإدارة الأعمال',2026,NULL,NULL,'2025/2026','د. عبد السلام رمضان العكروت','أستاذ التمويل المصرفي والأسواق المالية','[{\"name\":\"\\u0637\\u0647 \\u062d\\u0633\\u064a\\u0646 \\u0627\\u0644\\u0645\\u0634\\u0631\\u064a\",\"role\":\"\\u0627\\u0644\\u0646\\u0645\\u0630\\u062c\\u0629 \\u0627\\u0644\\u0645\\u0627\\u0644\\u064a\\u0629 \\u0627\\u0644\\u0625\\u062d\\u0635\\u0627\\u0626\\u064a\\u0629 \\u0648\\u0647\\u0646\\u062f\\u0633\\u0629 \\u0627\\u0644\\u0645\\u062e\\u0627\\u0637\\u0631\",\"email\":\"taha.m@tripoliuniversity.edu.ly\",\"phone\":\"+218 91 888 1122\",\"linkedin\":\"https:\\/\\/linkedin.com\"},{\"name\":\"\\u062e\\u062f\\u064a\\u062c\\u0629 \\u0645\\u0641\\u062a\\u0627\\u062d \\u0627\\u0644\\u0645\\u062c\\u0628\\u0631\\u064a\",\"role\":\"\\u062a\\u062d\\u0644\\u064a\\u0644 \\u0627\\u0644\\u0628\\u064a\\u0627\\u0646\\u0627\\u062a \\u0627\\u0644\\u0633\\u0648\\u0642\\u064a\\u0629 \\u0648\\u0627\\u0644\\u0645\\u0624\\u0634\\u0631\\u0627\\u062a \\u0627\\u0644\\u0628\\u062f\\u064a\\u0644\\u0629\",\"email\":\"khadija.m@tripoliuniversity.edu.ly\",\"phone\":\"+218 92 999 2233\",\"linkedin\":\"https:\\/\\/linkedin.com\"},{\"name\":\"\\u0632\\u0643\\u0631\\u064a\\u0627 \\u0646\\u0648\\u0631\\u064a \\u0628\\u0627\\u0644\\u0631\\u0627\\u0633 \\u0639\\u0644\\u064a\",\"role\":\"\\u062a\\u0635\\u0645\\u064a\\u0645 \\u0645\\u0646\\u0635\\u0629 \\u0627\\u0644\\u0631\\u0628\\u0637 \\u0627\\u0644\\u0645\\u0635\\u0631\\u0641\\u064a \\u0648\\u062a\\u062c\\u0631\\u0628\\u0629 \\u0627\\u0644\\u0645\\u0633\\u062a\\u062b\\u0645\\u0631\",\"email\":\"zakaria.b@tripoliuniversity.edu.ly\",\"phone\":\"+218 94 000 3344\",\"linkedin\":\"https:\\/\\/linkedin.com\"}]','منصة تقنية مالية (FinTech) تعتمد على المؤشرات البديلة وحركة المعاملات الرقمية لبناء سجل ائتماني دقيق للشركات الناشئة ورواد الأعمال لمساعدتهم في الحصول على التمويل المصرفي والاستثماري.',NULL,NULL,'• تيسير وصول أصحاب المشاريع الصغيرة لتمويلات مصرفية بدون اشتراط ضمانات عقارية تعجيزية.\n• تزويد المصارف الليبية بأداة تقييم مخاطر آلية وشفافة متوافقة مع الصيرفة الإسلامية.\n• تقليص دراسة الملف الائتماني من 3 أسابيع إلى أقل من 48 ساعة.','صمم الفريق خوارزمية ذكية تحتسب درجة الائتمان (Alternative Credit Score) بناءً على انتظام التدفقات النقدية، تقييم العملاء، والبيانات اللوجستية للمشروع. يشتمل النظام على بوابة للمصرف تظهر مؤشرات المخاطر وجدوى السداد المتوقعة بشفافية عالية.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'ECON-03','published',1,415,'2026-10-12 14:15:04','2026-10-12 14:15:04'),(7,1,NULL,'نظام التوثيق والتحقق من صحة الشهادات الأكاديمية اللامركزي بالاعتماد على البلوك تشين (Blockchain)','كلية تقنية المعلومات','الشبكات والأمن السيبراني',2026,NULL,NULL,'2025/2026','د. معتز سالم القذافي','أستاذ تقنيات السجلات الموزعة','[{\"name\":\"\\u064a\\u0648\\u0633\\u0641 \\u062c\\u0645\\u0627\\u0644 \\u0627\\u0644\\u062a\\u0627\\u0626\\u0628\",\"role\":\"\\u0645\\u0637\\u0648\\u0631 \\u0627\\u0644\\u0639\\u0642\\u0648\\u062f \\u0627\\u0644\\u0630\\u0643\\u064a\\u0629 (Smart Contracts \\/ Solidity)\",\"email\":\"youssef.t@tripoliuniversity.edu.ly\",\"phone\":\"+218 91 666 4433\",\"linkedin\":\"https:\\/\\/linkedin.com\"},{\"name\":\"\\u0631\\u064a\\u0647\\u0627\\u0645 \\u0639\\u0635\\u0627\\u0645 \\u0627\\u0644\\u0634\\u064a\\u0628\\u0627\\u0646\\u064a\",\"role\":\"\\u062a\\u0637\\u0648\\u064a\\u0631 \\u0648\\u0627\\u062c\\u0647\\u0627\\u062a \\u0627\\u0644\\u0645\\u0633\\u062a\\u062e\\u062f\\u0645 \\u0648\\u0627\\u0644\\u0631\\u0628\\u0637 \\u0645\\u0639 \\u0627\\u0644\\u0645\\u062d\\u0627\\u0641\\u0638 \\u0627\\u0644\\u0631\\u0642\\u0645\\u064a\\u0629\",\"email\":\"riham.s@tripoliuniversity.edu.ly\",\"phone\":\"+218 92 777 5544\",\"linkedin\":\"https:\\/\\/linkedin.com\"}]','منظومة جامعية لمنع تزوير الشهادات والوثائق الأكاديمية عبر إصدار شهادات رقمية مشفرة وغير قابلة للتعديل على شبكة البلوك تشين مع إمكانية التحقق الفوري برمز QR لأصحاب العمل حول العالم.',NULL,NULL,'• القضاء التام على ظاهرة تزوير المؤهلات العلمية والشهادات التدريبية.\n• تمكين أصحاب العمل والسفارات من التحقق اللحظي المجاني من الشهادة برمز QR في ثوانٍ.\n• منح الخريج ملكية كاملة لوثائقه الأكاديمية ضمن محفظة هوية رقمية معتمدة.','تعتمد المنصة على شبكة Polygon المتوافقة مع الإيثيريوم لتقليل تكلفة الغاز. تُمنح كل كلية مفتاح توقيع رقمي متعدد التواقيع (Multi-sig) لضمان اعتماد العميد والمسجل العام قبل تسجيل بصمة الوثيقة (Hash) على السلسلة إلى الأبد، مع حماية بيانات الخصوصية للخريج.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'https://github.com/blockchain-cert-verify',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'IT-07','published',0,378,'2026-10-12 14:15:04','2026-10-12 14:15:04'),(8,1,NULL,'منصة تفاعلية بالواقع الافتراضي (VR) لتوثيق وترميم التراث المعماري للمدينة القديمة طرابلس','كلية الفنون والإعلام','الفنون التشكيلية والوسائط المتعددة',2026,NULL,NULL,'2025/2026','أ.د. هدى عثمان الفقي','أستاذة الإعلام التفاعلي والفنون البصرية','[{\"name\":\"\\u0633\\u0646\\u062f\\u0633 \\u0639\\u0644\\u064a \\u0628\\u0627\\u0644\\u062d\\u0627\\u062c\",\"role\":\"\\u0627\\u0644\\u0645\\u0633\\u062d \\u0627\\u0644\\u0641\\u0648\\u062a\\u0648\\u063a\\u0631\\u0627\\u0645\\u062a\\u0631\\u064a \\u0648\\u0627\\u0644\\u0646\\u0645\\u0630\\u062c\\u0629 \\u062b\\u0644\\u0627\\u062b\\u064a\\u0629 \\u0627\\u0644\\u0623\\u0628\\u0639\\u0627\\u062f 3D\",\"email\":\"sondos.b@tripoliuniversity.edu.ly\",\"phone\":\"+218 91 333 9988\",\"linkedin\":\"https:\\/\\/linkedin.com\"},{\"name\":\"\\u0645\\u0639\\u0627\\u0630 \\u062c\\u0645\\u0639\\u0629 \\u0627\\u0644\\u062f\\u0631\\u0633\\u064a\",\"role\":\"\\u0628\\u0631\\u0645\\u062c\\u0629 \\u062a\\u0641\\u0627\\u0639\\u0644\\u064a\\u0629 \\u0648\\u0645\\u062d\\u0631\\u0643 \\u0627\\u0644\\u0623\\u0644\\u0639\\u0627\\u0628 (Unreal Engine 5)\",\"email\":\"moaz.d@tripoliuniversity.edu.ly\",\"phone\":\"+218 92 444 8877\",\"linkedin\":\"https:\\/\\/linkedin.com\"},{\"name\":\"\\u0644\\u064a\\u062b \\u0639\\u0628\\u062f \\u0627\\u0644\\u0633\\u0644\\u0627\\u0645 \\u0628\\u0627\\u062f\\u064a\",\"role\":\"\\u062a\\u0635\\u0645\\u064a\\u0645 \\u0627\\u0644\\u0625\\u0636\\u0627\\u0621\\u0629 \\u0648\\u0627\\u0644\\u0628\\u064a\\u0626\\u0627\\u062a \\u0627\\u0644\\u062a\\u0627\\u0631\\u064a\\u062e\\u064a\\u0629 \\u0648\\u0627\\u0644\\u0635\\u0648\\u062a \\u0627\\u0644\\u0645\\u0643\\u0627\\u0646\\u064a\",\"email\":\"laith.b@tripoliuniversity.edu.ly\",\"phone\":\"+218 94 555 7766\",\"linkedin\":\"https:\\/\\/linkedin.com\"}]','تجربة غامرة بنظارات الواقع الافتراضي (VR) وموقع ويب تفاعلي تقدم توثيقاً دقيقاً لمعالم مدينة طرابلس القديمة مع تصور رقمي افتراضي لترميم المباني التراثية المتضررة.',NULL,NULL,'• صون وتوثيق المعالم التاريخية رقمياً بمقاييس دقيقة تحفظ الهوية الليبية للأجيال القادمة.\n• تنشيط السياحة الافتراضية والترويج الثقافي لمعالم العاصمة محلياً ودولياً.\n• إتاحة قاعدة بيانات هندسية وبصرية ثلاثية الأبعاد لجهات الترميم والتخطيط الحضري.','استخدم الفريق تقنيات المسح بالليزر والفوتوغرامتري عالي الدقة لأكثر من 15 موقعاً أثرياً شملت أقواس وأسواق ومساجد تاريخية. تم بناء التجربة باستخدام Unreal Engine 5 مع محاكاة إضاءة واقعية، بحيث يستطيع الزائر التجول والتفاعل والاستماع للروايات التاريخية الموثقة لكل معلم.',NULL,NULL,NULL,NULL,NULL,NULL,'https://youtube.com/watch?v=tripoli-oldcity-vr',NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'ART-01','published',0,460,'2026-10-12 14:15:04','2026-10-12 14:15:04'),(9,1,NULL,'المنظومة الوطنية للرصد الوبائي الذكي والإنذار المبكر عبر نظم المعلومات الجغرافية الصحية (GIS-Health)','كلية الطب البشري','طب المجتمع والصحة العامة',2026,NULL,NULL,'2025/2026','د. الصديق إبراهيم المجذوب','استشاري الوبائيات والصحة العامة','[{\"name\":\"\\u0646\\u0648\\u0631 \\u0627\\u0644\\u0647\\u062f\\u0649 \\u0641\\u062a\\u062d\\u064a \\u0627\\u0644\\u0645\\u0628\\u0631\\u0648\\u0643\",\"role\":\"\\u062a\\u062d\\u0644\\u064a\\u0644 \\u0627\\u0644\\u0628\\u064a\\u0627\\u0646\\u0627\\u062a \\u0627\\u0644\\u0648\\u0628\\u0627\\u0626\\u064a\\u0629 \\u0648\\u0646\\u0645\\u0630\\u062c\\u0629 \\u0627\\u0646\\u062a\\u0634\\u0627\\u0631 \\u0627\\u0644\\u0639\\u062f\\u0648\\u0649\",\"email\":\"nour.m@tripoliuniversity.edu.ly\",\"phone\":\"+218 91 445 5667\",\"linkedin\":\"https:\\/\\/linkedin.com\"},{\"name\":\"\\u0623\\u0646\\u0633 \\u0639\\u062b\\u0645\\u0627\\u0646 \\u0642\\u0631\\u064a\\u0634\",\"role\":\"\\u062a\\u0637\\u0648\\u064a\\u0631 \\u062e\\u0631\\u0627\\u0626\\u0637 \\u0627\\u0644\\u062a\\u0648\\u0632\\u064a\\u0639 \\u0627\\u0644\\u0645\\u0643\\u0627\\u0646\\u064a \\u0648\\u0646\\u0638\\u0645 \\u0627\\u0644\\u0640 GIS\",\"email\":\"anas.q@tripoliuniversity.edu.ly\",\"phone\":\"+218 92 556 6778\",\"linkedin\":\"https:\\/\\/linkedin.com\"},{\"name\":\"\\u0628\\u0631\\u0627\\u0621\\u0629 \\u0643\\u0645\\u0627\\u0644 \\u0627\\u0644\\u0623\\u0633\\u0637\\u0649\",\"role\":\"\\u062a\\u0635\\u0645\\u064a\\u0645 \\u0628\\u0631\\u0648\\u062a\\u0648\\u0643\\u0648\\u0644\\u0627\\u062a \\u0627\\u0644\\u0625\\u0628\\u0644\\u0627\\u063a \\u0627\\u0644\\u0645\\u064a\\u062f\\u0627\\u0646\\u064a \\u0644\\u0644\\u0645\\u0631\\u0627\\u0643\\u0632 \\u0627\\u0644\\u0635\\u062d\\u064a\\u0629\",\"email\":\"baraa.o@tripoliuniversity.edu.ly\",\"phone\":\"+218 93 667 7889\",\"linkedin\":\"https:\\/\\/linkedin.com\"}]','منظومة وبائية رقمية تربط المستشفيات والمراكز الصحية في طرابلس برسم خرائط حرارية جغرافية لحظية لكشف بؤر تفشي الأمراض المعدية وتوزيع الموارد الطبية بكفاءة استباقية.',NULL,NULL,'• تقليص زمن الاستجابة للبؤر الوبائية الناشئة من أيام إلى بضع ساعات.\n• الربط الشبكي بين وحدات الرعاية الصحية الأولية والمركز الوطني لمكافحة الأمراض.\n• توجيه حملات التطعيم وتوزيع الأدوية بناءً على خوارزميات التنبؤ المكاني.','يتضمن النظام تطبيقاً لوحياً للأطباء في أقسام الطوارئ للإبلاغ الفوري المشفر، مع لوحة قيادة مركزية لوزارة الصحة تعرض المؤشرات الحيوية والتنبؤ بمسار انتشار العدوى باستخدام نماذج SIR الرياضية المدعمة بالتعلم الآلي.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'MED-02','published',1,340,'2026-10-12 14:15:04','2026-10-12 14:15:04'),(10,1,NULL,'نظام الزراعة الدقيقة والري الذكي ومراقبة الإجهاد المائي للمحاصيل عبر طائرات الدرون وإنترنت الأشياء','كلية الزراعة','الموارد الطبيعية والهندسة الزراعية',2026,NULL,NULL,'2025/2026','د. البشير الهادي بن رمضان','أستاذ إدارة المياه والتربة الزراعية','[{\"name\":\"\\u062d\\u0645\\u0632\\u0629 \\u0633\\u0644\\u064a\\u0645\\u0627\\u0646 \\u0627\\u0644\\u0634\\u0627\\u0648\\u0634\",\"role\":\"\\u062a\\u062d\\u0644\\u064a\\u0644 \\u0635\\u0648\\u0631 \\u0627\\u0644\\u0637\\u064a\\u0641 \\u0627\\u0644\\u0645\\u062a\\u0639\\u062f\\u062f (Multispectral) \\u0644\\u0644\\u062f\\u0631\\u0648\\u0646\",\"email\":\"hamza.s@tripoliuniversity.edu.ly\",\"phone\":\"+218 91 778 8990\",\"linkedin\":\"https:\\/\\/linkedin.com\"},{\"name\":\"\\u0633\\u0627\\u0631\\u0629 \\u0645\\u0633\\u0639\\u0648\\u062f \\u0627\\u0644\\u0641\\u064a\\u062a\\u0648\\u0631\\u064a\",\"role\":\"\\u0645\\u0639\\u0627\\u064a\\u0631\\u0629 \\u0645\\u062c\\u0633\\u0627\\u062a \\u0627\\u0644\\u0631\\u0637\\u0648\\u0628\\u0629 \\u0648\\u0627\\u0644\\u0645\\u0644\\u0648\\u062d\\u0629 \\u0627\\u0644\\u0644\\u0627\\u0633\\u0644\\u0643\\u064a\\u0629\",\"email\":\"sara.m@tripoliuniversity.edu.ly\",\"phone\":\"+218 92 889 9001\",\"linkedin\":\"https:\\/\\/linkedin.com\"}]','مشروع تطبيقي لمعالجة شح المياه في المشاريع الزراعية الليبية عبر شبكة حساسات رطوبة أرضية متصلة بمحطة ري ذكية ومحلل طيفي بصور الدرون لتحديد احتياج كل شجرة ومحصول بدقة.',NULL,NULL,'• توفير ما بين 35% إلى 50% من استهلاك المياه المخصصة للري السطحي والمحوري.\n• الكشف المبكر عن الآفات الزراعية ونقص التسميد قبل ظهور أعراضها بالعين المجردة.\n• تمكين المزارع من إدارة مشروعه بالكامل عبر تطبيق الهاتف الذكي باللغة العربية.','تم تطبيق النموذج الأولي على مزرعة تجريبية لأشجار الزيتون والحبوب بمنطقة وادي المجينين، حيث أثبت النظام قدرته على رصد مؤشر الغطاء النباتي (NDVI) وتوجيه صمامات الري الكهربائية ذاتياً استناداً لمعدلات البخر والنتح وبيانات الطقس المحلية.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'AGRI-05','published',0,270,'2026-10-12 14:15:04','2026-10-12 14:15:04'),(11,1,NULL,'تطوير خرسانة خضراء عالية المقاومة وصديقة للبيئة باستخدام مخلفات البناء والركام المعاد تدويره','كلية الهندسة','الهندسة المدنية والبيئية',2026,NULL,NULL,'2025/2026','د. سالم عاشور بن زاهية','أستاذ خواص ومقاومة المواد الإنشائية','[{\"name\":\"\\u0637\\u0627\\u0631\\u0642 \\u0641\\u0631\\u062c \\u0627\\u0644\\u0645\\u0646\\u0635\\u0648\\u0631\\u064a\",\"role\":\"\\u062a\\u0635\\u0645\\u064a\\u0645 \\u0627\\u0644\\u062e\\u0644\\u0637\\u0627\\u062a \\u0627\\u0644\\u062e\\u0631\\u0633\\u0627\\u0646\\u064a\\u0629 \\u0648\\u0627\\u062e\\u062a\\u0628\\u0627\\u0631\\u0627\\u062a \\u0627\\u0644\\u0625\\u062c\\u0647\\u0627\\u062f \\u0648\\u0627\\u0644\\u0643\\u0633\\u0631\",\"email\":\"tarek.m@tripoliuniversity.edu.ly\",\"phone\":\"+218 91 990 0112\",\"linkedin\":\"https:\\/\\/linkedin.com\"},{\"name\":\"\\u0639\\u0627\\u0626\\u0634\\u0629 \\u0646\\u0648\\u0631\\u064a \\u0627\\u0644\\u063a\\u0631\\u064a\\u0627\\u0646\\u064a\",\"role\":\"\\u0627\\u0644\\u062f\\u0631\\u0627\\u0633\\u0627\\u062a \\u0627\\u0644\\u0645\\u064a\\u0643\\u0631\\u0648\\u0633\\u0643\\u0648\\u0628\\u064a\\u0629 \\u0648\\u0627\\u0644\\u0645\\u062a\\u0627\\u0646\\u0629 \\u0627\\u0644\\u0643\\u064a\\u0645\\u064a\\u0627\\u0626\\u064a\\u0629\",\"email\":\"aisha.g@tripoliuniversity.edu.ly\",\"phone\":\"+218 92 001 1223\",\"linkedin\":\"https:\\/\\/linkedin.com\"}]','ابتكار خلطة خرسانية مستدامة تعتمد على إعادة تدوير مخلفات الهدم والركام الإسمنتي بنسبة استبدال تصل إلى 40%، مما يخفف من التلوث البيئي ويقلل تكلفة المشاريع السكنية.',NULL,NULL,'• خفض البصمة الكربونية لإنتاج الخرسانة المسلحة بنسبة 30%.\n• استثمار ركام مخلفات البناء المتراكمة في ضواحي طرابلس وحماية البيئة العمرانية.\n• تحقيق مقاومة ضغط تتجاوز 35 ميجاباسكال تلائم المنشآت متعددة الطوابق.','أجرى الفريق أكثر من 80 اختبار كسر وضغط ومقاومة كبريتات في معامل كلية الهندسة، وتم التوصل إلى صيغة كيميائية تستخدم خبث الأفران والركام المعالج لإنتاج بلوكات خرسانية وعناصر مسبقة الصب تمتاز بعزل حراري أعلى وتكلفة أقل بنسبة 22%.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'ENG-18','published',0,310,'2026-10-12 14:15:04','2026-10-12 14:15:04'),(12,1,NULL,'منصة \"عدالة الرقمية\" للتحليل الذكي للعقود التجارية وصياغة النماذج القانونية للشركات الناشئة','كلية القانون','القانون التجاري والملكية الفكرية',2026,NULL,NULL,'2025/2026','د. نجوى عبد الله المقريف','أستاذة التشريعات الرقمية وقانون المعاملات','[{\"name\":\"\\u0625\\u0633\\u0631\\u0627\\u0621 \\u0639\\u0628\\u062f \\u0627\\u0644\\u0633\\u0644\\u0627\\u0645 \\u0627\\u0644\\u0639\\u0632\\u0627\\u0628\\u064a\",\"role\":\"\\u0635\\u064a\\u0627\\u063a\\u0629 \\u0627\\u0644\\u0642\\u0648\\u0627\\u0644\\u0628 \\u0627\\u0644\\u0642\\u0627\\u0646\\u0648\\u0646\\u064a\\u0629 \\u0648\\u0645\\u0648\\u0627\\u0621\\u0645\\u0629 \\u0627\\u0644\\u062a\\u0634\\u0631\\u064a\\u0639\\u0627\\u062a \\u0627\\u0644\\u0644\\u064a\\u0628\\u064a\\u0629\",\"email\":\"esraa.a@tripoliuniversity.edu.ly\",\"phone\":\"+218 91 123 7890\",\"linkedin\":\"https:\\/\\/linkedin.com\"},{\"name\":\"\\u0645\\u0639\\u062a\\u0632 \\u0628\\u0627\\u0644\\u0644\\u0647 \\u0639\\u0628\\u062f \\u0627\\u0644\\u0631\\u0632\\u0627\\u0642\",\"role\":\"\\u062a\\u0635\\u0646\\u064a\\u0641 \\u0628\\u0646\\u0648\\u062f \\u0627\\u0644\\u0639\\u0642\\u0648\\u062f \\u0648\\u062a\\u062f\\u0631\\u064a\\u0628 \\u0646\\u0645\\u0627\\u0630\\u062c \\u0645\\u0639\\u0627\\u0644\\u062c\\u0629 \\u0627\\u0644\\u0644\\u063a\\u0629 (NLP)\",\"email\":\"moataz.r@tripoliuniversity.edu.ly\",\"phone\":\"+218 92 234 8901\",\"linkedin\":\"https:\\/\\/linkedin.com\"}]','منصة تقنية قانونية (LegalTech) تستند إلى معالجة اللغات الطبيعية (NLP) لمراجعة العقود والاتفاقيات التجارية طبقاً للقانون التجاري الليبي وتنبيه رواد الأعمال للثغرات القانونية.',NULL,NULL,'• تمكين الشركات الناشئة وأصحاب الأعمال الحرة من الحصول على صياغات قانونية محكمة بتكلفة ميسرة.\n• تدقيق العقود واستكشاف البنود المجحفة ومخاطر المسؤولية المدنية والجزائية آلياً.\n• نشر الثقافة القانونية وحماية حقوق الملكية الفكرية للمبتكرين والباحثين.','تم تدريب نموذج ذكاء اصطناعي عربي متخصص على أكثر من 3000 عقد وحكم قضائي وقانون تجاري ليبي ومقارن، لتوليد عقود الشراكة، وتوزيع الحصص، واتفاقيات عدم الإفصاح (NDA)، وعقود التوظيف مع تدقيق فوري ومراجعة الصياغات.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'https://github.com/adalah-legaltech',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'LAW-04','published',1,365,'2026-10-12 14:15:04','2026-10-12 14:15:04');
