  KEY `job_fair_registrations_user_id_foreign` (`user_id`),
  CONSTRAINT `job_fair_registrations_job_fair_id_foreign` FOREIGN KEY (`job_fair_id`) REFERENCES `job_fairs` (`id`) ON DELETE CASCADE,
  CONSTRAINT `job_fair_registrations_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
