INSERT INTO `survey_templates` VALUES (1,'استبيان قياس أثر البرنامج التدريبي ورضا المتدربين','نموذج شامل لقياس جودة التدريب، كفاءة المدرب، ملائمة المادة العلمية، والمهارات المكتسبة لسوق العمل بعد انتهاء البرنامج.','training','graduates','training','[{\"question\":\"\\u0645\\u0627 \\u0645\\u062f\\u0649 \\u062a\\u0642\\u064a\\u064a\\u0645\\u0643 \\u0627\\u0644\\u0639\\u0627\\u0645 \\u0644\\u062c\\u0648\\u062f\\u0629 \\u0627\\u0644\\u0628\\u0631\\u0646\\u0627\\u0645\\u062c \\u0627\\u0644\\u062a\\u062f\\u0631\\u064a\\u0628\\u064a\\u061f\",\"type\":\"rating\",\"max_rating\":5,\"required\":true,\"description\":\"1 \\u064a\\u0639\\u0646\\u064a \\u0636\\u0639\\u064a\\u0641 \\u062c\\u062f\\u0627\\u064b\\u060c 5 \\u064a\\u0639\\u0646\\u064a \\u0645\\u0645\\u062a\\u0627\\u0632\"},{\"question\":\"\\u062a\\u0645\\u0643\\u0646 \\u0627\\u0644\\u0645\\u062f\\u0631\\u0628 \\u0645\\u0646 \\u0627\\u0644\\u0645\\u0627\\u062f\\u0629 \\u0627\\u0644\\u0639\\u0644\\u0645\\u064a\\u0629 \\u0648\\u0642\\u062f\\u0631\\u062a\\u0647 \\u0639\\u0644\\u0649 \\u0625\\u064a\\u0635\\u0627\\u0644 \\u0627\\u0644\\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062a \\u0628\\u0633\\u0644\\u0627\\u0633\\u0629\",\"type\":\"rating\",\"max_rating\":5,\"required\":true,\"description\":\"\\u062a\\u0642\\u064a\\u064a\\u0645 \\u0623\\u062f\\u0627\\u0621 \\u0627\\u0644\\u0645\\u062f\\u0631\\u0628 \\u0648\\u062a\\u0641\\u0627\\u0639\\u0644\\u0647 \\u0645\\u0639 \\u0627\\u0644\\u0645\\u062a\\u062f\\u0631\\u0628\\u064a\\u0646\"},{\"question\":\"\\u0645\\u062f\\u0649 \\u0648\\u0636\\u0648\\u062d \\u0627\\u0644\\u0645\\u062d\\u062a\\u0648\\u0649 \\u0627\\u0644\\u062a\\u062f\\u0631\\u064a\\u0628\\u064a \\u0648\\u0645\\u0644\\u0627\\u0621\\u0645\\u0629 \\u0627\\u0644\\u062a\\u0637\\u0628\\u064a\\u0642\\u0627\\u062a \\u0627\\u0644\\u0639\\u0645\\u0644\\u064a\\u0629 \\u0644\\u0627\\u062d\\u062a\\u064a\\u0627\\u062c\\u0627\\u062a \\u0633\\u0648\\u0642 \\u0627\\u0644\\u0639\\u0645\\u0644\",\"type\":\"rating\",\"max_rating\":5,\"