  `description` text NOT NULL,
  `type` varchar(255) NOT NULL,
  `duration` varchar(255) NOT NULL,
  `start_date` date NOT NULL,
  `end_date` date NOT NULL,
  `training_days_of_week` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`training_days_of_week`)),
  `location` varchar(255) NOT NULL,
  `seats` int(11) NOT NULL,
  `status` varchar(255) NOT NULL DEFAULT 'active',
  `company_id` bigint(20) unsigned DEFAULT NULL,
  `coordinator_id` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `category` varchar(255) DEFAULT NULL,
  `requirements` text DEFAULT NULL,
  `objectives` text DEFAULT NULL,
  `instructor_name` varchar(255) DEFAULT NULL,
  `instructor_qualifications` varchar(255) DEFAULT NULL,
  `media_coverage_status` enum('pending','covered','not_required') NOT NULL DEFAULT 'pending',
  `media_coverage_summary` text DEFAULT NULL COMMENT 'ملخص التغطية الصحفية والإعلامية',
  `media_press_release` text DEFAULT NULL COMMENT 'البيان الصحفي المعتمد',
  `media_coverage_notes` text DEFAULT NULL COMMENT 'ملاحظات وتوصيات الفريق الإعلامي',
  `media_team_members` varchar(255) DEFAULT NULL COMMENT 'فريق التغطية والمصورين',
  `media_coverage_links` text DEFAULT NULL COMMENT 'روابط النشر على المنصات والسوشيال ميديا',
